int i = 1;
int cift = 0, tek = 0;
while (i <= 6) {
    if (i % 2 == 0) {
        cift += i;
    } else {
        tek += i;
    }
    i++;
}
System.out.println(cift + " " + tek + " " + i);

int toplam = 0;
for (int k = 3; k > 0; k--) {
    switch (k) {
        case 3: toplam += 10;
        case 2: toplam += 5; break;
        default: toplam += 1;
    }
}
System.out.println(toplam + " " + toplam / 4 + " " + toplam / 4.0);

